//! The hash kernels against Spark 4.0, 4.1 and 4.2 on seeded random inputs
//! (`tests/fixtures/spark-4.2.0/hash-differential.json`, generated by
//! `tests/scripts/gen_hash_differential.py`; the three versions agree):
//! binary of every length to 100 bytes, strings, every fixed-width type with
//! edge values, wide decimals, nested values with NULLs, column chains, and
//! the digests with every `sha2` bit length.
#![forbid(unsafe_code)]

use std::sync::Arc;

use arrow_array::types::Int32Type;
use arrow_array::{
    Array, ArrayRef, BinaryArray, BooleanArray, Date32Array, Decimal128Array, Float32Array,
    Float64Array, Int8Array, Int16Array, Int32Array, Int64Array, ListArray, MapArray, StringArray,
    StructArray, TimestampMicrosecondArray,
};
use arrow_buffer::{NullBuffer, OffsetBuffer};
use arrow_schema::{DataType, Field, Fields};
use krishiv_kernels::Operand;
use krishiv_kernels::hash::{crc32, hash, md5, sha1, sha2, xxhash64};
use serde_json::Value;

type R = Result<(), Box<dyn std::error::Error>>;
type E = Box<dyn std::error::Error>;

fn float(v: &Value) -> Option<f64> {
    match v {
        Value::Null => None,
        Value::String(s) => Some(match s.as_str() {
            "nan" => f64::NAN,
            "inf" => f64::INFINITY,
            _ => f64::NEG_INFINITY,
        }),
        v => v.as_f64(),
    }
}

fn unscaled(v: &Value) -> Option<i128> {
    v.as_str().and_then(|s| s.parse().ok())
}

fn bytes(v: &Value) -> Option<Vec<u8>> {
    v.as_str().map(|h| {
        (0..h.len())
            .step_by(2)
            .filter_map(|i| u8::from_str_radix(h.get(i..i + 2)?, 16).ok())
            .collect()
    })
}

fn nulls_of(values: &[Value]) -> Option<NullBuffer> {
    values
        .iter()
        .any(Value::is_null)
        .then(|| NullBuffer::from(values.iter().map(|v| !v.is_null()).collect::<Vec<_>>()))
}

fn int_type(name: &str) -> Result<DataType, E> {
    Ok(match name {
        "int" => DataType::Int32,
        "string" => DataType::Utf8,
        other => return Err(format!("type {other}").into()),
    })
}

/// A column of `values` (JSON, one per row) of Spark type `ty`.
#[expect(
    clippy::cast_possible_truncation,
    reason = "a float column rounds the recorded double to f32, as Spark's Python bridge does"
)]
fn column(ty: &str, values: &[Value]) -> Result<ArrayRef, E> {
    let each =
        |f: &dyn Fn(&Value) -> Option<i64>| -> Vec<Option<i64>> { values.iter().map(f).collect() };
    let i64s = each(&|v| v.as_i64());
    let narrow = |v: Option<i64>| v.and_then(|v| i32::try_from(v).ok());
    Ok(match ty {
        "tinyint" => Arc::new(Int8Array::from_iter(
            i64s.iter().map(|v| v.and_then(|v| i8::try_from(v).ok())),
        )),
        "smallint" => Arc::new(Int16Array::from_iter(
            i64s.iter().map(|v| v.and_then(|v| i16::try_from(v).ok())),
        )),
        "int" => Arc::new(Int32Array::from_iter(i64s.iter().map(|v| narrow(*v)))),
        "date" => Arc::new(Date32Array::from_iter(i64s.iter().map(|v| narrow(*v)))),
        "bigint" => Arc::new(Int64Array::from(i64s)),
        "timestamp" => Arc::new(TimestampMicrosecondArray::from(i64s)),
        "boolean" => Arc::new(BooleanArray::from_iter(values.iter().map(Value::as_bool))),
        // Rounding the double is the float conversion Spark's Python bridge makes.
        "float" => Arc::new(Float32Array::from_iter(
            values.iter().map(|v| float(v).map(|f| f as f32)),
        )),
        "double" => Arc::new(Float64Array::from_iter(values.iter().map(float))),
        "string" => Arc::new(StringArray::from_iter(values.iter().map(Value::as_str))),
        "binary" => {
            let b: Vec<Option<Vec<u8>>> = values.iter().map(bytes).collect();
            Arc::new(BinaryArray::from_iter(b.iter().map(|v| v.as_deref())))
        }
        "decimal(18,4)" => Arc::new(
            Decimal128Array::from_iter(values.iter().map(unscaled))
                .with_precision_and_scale(18, 4)?,
        ),
        "decimal(38,6)" => Arc::new(
            Decimal128Array::from_iter(values.iter().map(unscaled))
                .with_precision_and_scale(38, 6)?,
        ),
        "array<int>" | "array<string>" | "array<struct<a:int,b:string>>" => {
            let el = &ty["array<".len()..ty.len() - 1];
            let rows: Vec<&[Value]> = values
                .iter()
                .map(|v| v.as_array().map_or(&[][..], Vec::as_slice))
                .collect();
            let flat: Vec<Value> = rows.iter().flat_map(|r| r.iter().cloned()).collect();
            let child = column(el, &flat)?;
            Arc::new(ListArray::new(
                Arc::new(Field::new("item", child.data_type().clone(), true)),
                OffsetBuffer::from_lengths(rows.iter().map(|r| r.len())),
                child,
                nulls_of(values),
            ))
        }
        "struct<a:int,b:string>" => {
            let part = |i: usize| -> Vec<Value> {
                values
                    .iter()
                    .map(|v| v.get(i).cloned().unwrap_or(Value::Null))
                    .collect()
            };
            let (a, b) = (column("int", &part(0))?, column("string", &part(1))?);
            let fields = Fields::from(vec![
                Field::new("a", int_type("int")?, true),
                Field::new("b", int_type("string")?, true),
            ]);
            Arc::new(StructArray::new(fields, vec![a, b], nulls_of(values)))
        }
        "map<string,int>" => {
            let rows: Vec<&[Value]> = values
                .iter()
                .map(|v| v.as_array().map_or(&[][..], Vec::as_slice))
                .collect();
            let pairs: Vec<&Value> = rows.iter().flat_map(|r| r.iter()).collect();
            let keys = column(
                "string",
                &pairs.iter().map(|p| p[0].clone()).collect::<Vec<_>>(),
            )?;
            let vals = column(
                "int",
                &pairs.iter().map(|p| p[1].clone()).collect::<Vec<_>>(),
            )?;
            let kv = Fields::from(vec![
                Field::new("key", DataType::Utf8, false),
                Field::new("value", DataType::Int32, true),
            ]);
            let entries = Field::new("entries", DataType::Struct(kv.clone()), false);
            Arc::new(MapArray::new(
                Arc::new(entries),
                OffsetBuffer::from_lengths(rows.iter().map(|r| r.len())),
                StructArray::new(kv, vec![keys, vals], None),
                nulls_of(values),
                false,
            ))
        }
        other => return Err(format!("type {other}").into()),
    })
}

fn fixture() -> Result<Value, E> {
    let path = krishiv_testkit::tests_dir().join("fixtures/spark-4.2.0/hash-differential.json");
    Ok(serde_json::from_str(&std::fs::read_to_string(path)?)?)
}

fn ints(v: &Value) -> Vec<Option<i64>> {
    v.as_array()
        .map_or_else(Vec::new, |a| a.iter().map(Value::as_i64).collect())
}

#[test]
fn hash_and_xxhash64_match_spark() -> R {
    let fx = fixture()?;
    let mut checked = 0;
    for g in fx["groups"].as_array().ok_or("groups")? {
        let Some(types) = g.get("types").and_then(Value::as_array) else {
            continue;
        };
        let rows = g["rows"].as_array().ok_or("rows")?;
        let cols: Vec<ArrayRef> = types
            .iter()
            .enumerate()
            .map(|(i, t)| {
                let vals: Vec<Value> = rows.iter().map(|r| r[i].clone()).collect();
                column(t.as_str().unwrap_or_default(), &vals)
            })
            .collect::<Result<_, _>>()?;
        let refs: Vec<&dyn Array> = cols.iter().map(AsRef::as_ref).collect();
        let name = g["name"].as_str().unwrap_or_default();
        let h = hash(&refs, rows.len())?;
        let x = xxhash64(&refs, rows.len())?;
        for (i, (eh, ex)) in ints(&g["hash"])
            .iter()
            .zip(ints(&g["xxhash64"]))
            .enumerate()
        {
            assert_eq!(
                Some(i64::from(h.value(i))),
                *eh,
                "{name} hash row {i}: {}",
                rows[i]
            );
            assert_eq!(Some(x.value(i)), ex, "{name} xxhash64 row {i}: {}", rows[i]);
            checked += 1;
        }
    }
    assert!(checked > 1000, "only {checked} rows");
    Ok(())
}

#[test]
fn digests_match_spark() -> R {
    let fx = fixture()?;
    let bits_list: Vec<Option<i32>> = fx["sha2_bits"]
        .as_array()
        .ok_or("sha2_bits")?
        .iter()
        .map(|b| b.as_i64().and_then(|b| i32::try_from(b).ok()))
        .collect();
    let strs = |v: &Value| -> Vec<Option<String>> {
        v.as_array()
            .map(|a| a.iter().map(|s| s.as_str().map(str::to_owned)).collect())
            .unwrap_or_default()
    };
    for g in fx["groups"].as_array().ok_or("groups")? {
        let Some(ty) = g.get("type").and_then(Value::as_str) else {
            continue;
        };
        let rows = g["rows"].as_array().ok_or("rows")?;
        let col = column(ty, rows)?;
        let name = g["name"].as_str().unwrap_or_default();
        let got = |a: StringArray| -> Vec<Option<String>> {
            a.iter().map(|s| s.map(str::to_owned)).collect()
        };
        assert_eq!(got(md5(col.as_ref())?), strs(&g["md5"]), "{name} md5");
        assert_eq!(got(sha1(col.as_ref())?), strs(&g["sha1"]), "{name} sha1");
        assert_eq!(
            crc32(col.as_ref())?.iter().collect::<Vec<_>>(),
            ints(&g["crc32"]),
            "{name} crc32"
        );
        for bits in &bits_list {
            let key = bits.map_or_else(
                || "sha2_null".to_owned(),
                |b| format!("sha2_{}", b.to_string().replace('-', "m")),
            );
            let scalar: Operand<'_, Int32Type> = Operand::Scalar(*bits);
            assert_eq!(
                got(sha2(col.as_ref(), scalar)?),
                strs(&g[key.as_str()]),
                "{name} {key}"
            );
        }
    }
    Ok(())
}
